def D(t,m,tags,p,s,x,r,h,kind=None):
    d=dict(t=t,m=m,tags=tags,p=p,s=s.lstrip('\n'),x=x.strip('\n'),r=r.lstrip('\n'),h=h)
    if kind: d['kind']=kind
    return d
